from pyspark.sql import functions as F


def solve(transactions):
    category = (
        F.when(F.col("direction") == "credit", "income")
        .when(F.col("txn_type") == "refund", "refund")
        .when(F.col("txn_type") == "fee", "bank_fee")
        .otherwise("spending")
    )
    return transactions.select("transaction_id", "txn_type", "direction", category.alias("category"))
